{
  "name": "FlitsWoord",
  "description": "Een interactieve tool voor leerkrachten om woorden te flitsen in de klas. Ondersteunt handmatige invoer en AI-gegenereerde woordenlijsten."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum AppPhase {
  SETUP = 'SETUP',
  SESSION = 'SESSION',
  FINISHED = 'FINISHED'
}

export enum SessionPhase {
  COUNTDOWN = 'COUNTDOWN', // 3, 2, 1
  DISPLAY = 'DISPLAY',     // Show word
  WAITING = 'WAITING'      // Word hidden, waiting for teacher
}

export interface WordConfig {
  words: string[];
  displayDuration: number; // in seconds
}

import { GoogleGenAI, Type } from "@google/genai";

const apiKey = process.env.API_KEY || '';

export const generateWordList = async (topic: string, count: number = 10): Promise<string[]> => {
  if (!apiKey) {
    console.warn("API Key is missing. Returning fallback data.");
    return ['vis', 'aap', 'noot', 'mies', 'vuur'];
  }

  try {
    const ai = new GoogleGenAI({ apiKey });

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Genereer een lijst van ${count} Nederlandse woorden die te maken hebben met het thema "${topic}". De woorden moeten geschikt zijn voor basisschoolleerlingen (groep 3-8).`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.STRING
          }
        }
      }
    });

    const text = response.text;
    if (!text) return [];

    const words = JSON.parse(text);
    return Array.isArray(words) ? words : [];
  } catch (error) {
    console.error("Error generating word list:", error);
    throw new Error("Kon geen woorden genereren. Probeer het opnieuw of voer ze handmatig in.");
  }
};

import React, { useState } from 'react';
import { WordConfig } from '../types';
import { generateWordList } from '../services/geminiService';
import { Sparkles, Play, List, Settings2, Eraser } from 'lucide-react';

interface SetupScreenProps {
  onStart: (config: WordConfig) => void;
}

const SetupScreen: React.FC<SetupScreenProps> = ({ onStart }) => {
  const [textInput, setTextInput] = useState('');
  const [topicInput, setTopicInput] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [displayTime, setDisplayTime] = useState(5);
  const [activeTab, setActiveTab] = useState<'manual' | 'ai'>('manual');

  const handleStart = () => {
    const words = textInput
      .split(/[\n,]+/)
      .map(w => w.trim())
      .filter(w => w.length > 0);

    if (words.length === 0) {
      alert("Voer ten minste één woord in om te starten.");
      return;
    }

    onStart({
      words,
      displayDuration: displayTime
    });
  };

  const handleGenerate = async () => {
    if (!topicInput.trim()) return;

    setIsGenerating(true);
    try {
      const words = await generateWordList(topicInput, 15);
      setTextInput(words.join('\n'));
      setActiveTab('manual'); // Switch to manual view to let user edit
    } catch (e) {
      alert("Er ging iets mis bij het genereren.");
    } finally {
      setIsGenerating(false);
    }
  };

  const clearWords = () => {
    if(confirm('Weet je zeker dat je de lijst wilt wissen?')) {
        setTextInput('');
    }
  }

  return (
    <div className="max-w-2xl mx-auto p-6">
      <div className="text-center mb-10">
        <h1 className="text-4xl font-display font-bold text-indigo-600 mb-2">FlitsWoord</h1>
        <p className="text-slate-500">Bereid je flitsles voor de klas voor.</p>
      </div>

      <div className="bg-white rounded-2xl shadow-xl overflow-hidden border border-slate-100">
        {/* Tabs */}
        <div className="flex border-b border-slate-100">
          <button
            onClick={() => setActiveTab('manual')}
            className={`flex-1 py-4 text-sm font-semibold flex items-center justify-center gap-2 transition-colors ${
              activeTab === 'manual' ? 'bg-indigo-50 text-indigo-600 border-b-2 border-indigo-600' : 'text-slate-500 hover:text-slate-700'
            }`}
          >
            <List size={18} />
            Handmatige invoer
          </button>
          <button
            onClick={() => setActiveTab('ai')}
            className={`flex-1 py-4 text-sm font-semibold flex items-center justify-center gap-2 transition-colors ${
              activeTab === 'ai' ? 'bg-purple-50 text-purple-600 border-b-2 border-purple-600' : 'text-slate-500 hover:text-slate-700'
            }`}
          >
            <Sparkles size={18} />
            AI Generator
          </button>
        </div>

        <div className="p-8">
          {activeTab === 'manual' ? (
            <div className="space-y-4">
              <label className="block text-sm font-medium text-slate-700">
                Typ of plak je woordenlijst (één per regel of gescheiden door komma's)
              </label>
              <div className="relative">
                <textarea
                    value={textInput}
                    onChange={(e) => setTextInput(e.target.value)}
                    placeholder="vis&#10;aap&#10;noot&#10;..."
                    className="w-full h-64 p-4 rounded-xl border border-slate-200 focus:border-indigo-500 focus:ring-2 focus:ring-indigo-200 outline-none resize-none font-display text-lg shadow-inner"
                />
                {textInput.length > 0 && (
                     <button 
                        onClick={clearWords}
                        className="absolute top-4 right-4 text-slate-400 hover:text-red-500 transition-colors p-1"
                        title="Lijst wissen"
                     >
                        <Eraser size={20} />
                     </button>
                )}
              </div>
              <div className="text-right text-xs text-slate-400">
                {textInput.split(/[\n,]+/).filter(w => w.trim().length > 0).length} woorden
              </div>
            </div>
          ) : (
            <div className="space-y-6 py-8">
              <div className="text-center space-y-2">
                <div className="inline-flex items-center justify-center w-12 h-12 rounded-full bg-purple-100 text-purple-600 mb-2">
                  <Sparkles size={24} />
                </div>
                <h3 className="text-lg font-semibold text-slate-900">Laat AI een lijst maken</h3>
                <p className="text-sm text-slate-500 max-w-xs mx-auto">
                    Vul een thema in (bijv. "Lente", "Werkwoorden", "Dieren") en wij genereren een woordenlijst.
                </p>
              </div>

              <div className="flex gap-2">
                <input
                  type="text"
                  value={topicInput}
                  onChange={(e) => setTopicInput(e.target.value)}
                  onKeyDown={(e) => e.key === 'Enter' && handleGenerate()}
                  placeholder="Bijv: Groenten en fruit"
                  className="flex-1 p-3 rounded-lg border border-slate-200 focus:border-purple-500 focus:ring-2 focus:ring-purple-200 outline-none"
                />
                <button
                  onClick={handleGenerate}
                  disabled={isGenerating || !topicInput.trim()}
                  className="bg-purple-600 text-white px-6 rounded-lg font-medium hover:bg-purple-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
                >
                  {isGenerating ? 'Bezig...' : 'Genereer'}
                </button>
              </div>
            </div>
