import React, { useState } from 'react';
import SetupScreen from './components/SetupScreen';
import SessionScreen from './components/SessionScreen';
import CompletionScreen from './components/CompletionScreen';
import { AppPhase, WordConfig } from './types';

const App: React.FC = () => {
  const [phase, setPhase] = useState<AppPhase>(AppPhase.SETUP);
  const [config, setConfig] = useState<WordConfig>({ words: [], displayDuration: 5 });

  const startSession = (newConfig: WordConfig) => {
    setConfig(newConfig);
    setPhase(AppPhase.SESSION);
  };

  const handleComplete = () => {
    setPhase(AppPhase.FINISHED);
  };

  const handleRestart = () => {
    setPhase(AppPhase.SESSION);
  };

  const handleEdit = () => {
    setPhase(AppPhase.SETUP);
  };

  return (
    <div className="min-h-screen bg-slate-50">
      {phase === AppPhase.SETUP && (
        <SetupScreen onStart={startSession} />
      )}

      {phase === AppPhase.SESSION && (
        <SessionScreen 
          config={config} 
          onComplete={handleComplete}
          onExit={handleEdit}
        />
      )}

      {phase === AppPhase.FINISHED && (
        <CompletionScreen 
          onRestart={handleRestart} 
          onEdit={handleEdit}
          wordCount={config.words.length}
        />
      )}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { WordConfig } from '../types';
import { generateWordList } from '../services/geminiService';
import { Sparkles, Play, List, Settings2, Eraser } from 'lucide-react';

interface SetupScreenProps {
  onStart: (config: WordConfig) => void;
}

const SetupScreen: React.FC<SetupScreenProps> = ({ onStart }) => {
  const [textInput, setTextInput] = useState('');
  const [topicInput, setTopicInput] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [displayTime, setDisplayTime] = useState(5);
  const [activeTab, setActiveTab] = useState<'manual' | 'ai'>('manual');

  const handleStart = () => {
    const words = textInput
      .split(/[\n,]+/)
      .map(w => w.trim())
      .filter(w => w.length > 0);

    if (words.length === 0) {
      alert("Voer ten minste één woord in om te starten.");
      return;
    }

    onStart({
      words,
      displayDuration: displayTime
    });
  };

  const handleGenerate = async () => {
    if (!topicInput.trim()) return;

    setIsGenerating(true);
    try {
      const words = await generateWordList(topicInput, 15);
      setTextInput(words.join('\n'));
      setActiveTab('manual'); // Switch to manual view to let user edit
    } catch (e) {
      alert("Er ging iets mis bij het genereren.");
    } finally {
      setIsGenerating(false);
    }
  };

  const clearWords = () => {
    if(confirm('Weet je zeker dat je de lijst wilt wissen?')) {
        setTextInput('');
    }
