export const dbService = {
  getMethods: async (): Promise<Method[]> => {
    // Simulatie van: SELECT * FROM methods
    return new Promise((resolve) => {
      setTimeout(() => resolve(METHODS_TABLE), 300);
    });
  },

  getYearsForMethod: async (methodId: number): Promise<number[]> => {
    // Simulatie van: SELECT DISTINCT year FROM chapters WHERE method_id = ?
    return new Promise((resolve) => {
      setTimeout(() => {
        const years = Array.from(new Set(
          CHAPTERS_TABLE
            .filter(c => c.method_id === methodId)
            .map(c => c.year)
        )).sort((a, b) => a - b);
        resolve(years);
      }, 300);
    });
  },

  getChapters: async (methodId: number, year: number): Promise<Chapter[]> => {
    // Simulatie van: SELECT * FROM chapters WHERE method_id = ? AND year = ?
    return new Promise((resolve) => {
      setTimeout(() => {
        resolve(CHAPTERS_TABLE.filter(c => c.method_id === methodId && c.year === year));
      }, 300);
    });
  },

  getWordsByChapter: async (chapterId: number): Promise<string[]> => {
    // Simulatie van: SELECT text FROM words WHERE chapter_id = ?
    return new Promise((resolve) => {
      setTimeout(() => {
        const words = WORDS_TABLE
          .filter(w => w.chapter_id === chapterId)
          .map(w => w.text);
        resolve(words);
      }, 300);
    });
  }
};

import React, { useState, useEffect } from 'react';
import { WordConfig } from '../types';
import { generateWordList } from '../services/geminiService';
import { dbService, Method, Chapter } from '../services/databaseService';
import { Sparkles, Play, List, Settings2, Eraser, BookOpen, GraduationCap } from 'lucide-react';

interface SetupScreenProps {
  onStart: (config: WordConfig) => void;
}

const SetupScreen: React.FC<SetupScreenProps> = ({ onStart }) => {
  const [textInput, setTextInput] = useState('');
  const [topicInput, setTopicInput] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [displayTime, setDisplayTime] = useState(5);
  const [activeTab, setActiveTab] = useState<'manual' | 'ai' | 'method'>('manual');

  // Database State
  const [methods, setMethods] = useState<Method[]>([]);
  const [years, setYears] = useState<number[]>([]);
  const [chapters, setChapters] = useState<Chapter[]>([]);

  const [selectedMethodId, setSelectedMethodId] = useState<number | ''>('');
  const [selectedYear, setSelectedYear] = useState<number | ''>('');
  const [selectedChapterId, setSelectedChapterId] = useState<number | ''>('');
  const [isLoadingDB, setIsLoadingDB] = useState(false);

  // Load methods on mount
  useEffect(() => {
    const loadMethods = async () => {
      try {
        const data = await dbService.getMethods();
        setMethods(data);
      } catch (err) {
        console.error("Failed to load methods", err);
      }
    };
    loadMethods();
  }, []);

  const handleMethodChange = async (methodId: number) => {
    setSelectedMethodId(methodId);
    setSelectedYear('');
    setSelectedChapterId('');
    setYears([]);
    setChapters([]);

    if (methodId) {
      setIsLoadingDB(true);
      const data = await dbService.getYearsForMethod(methodId);
      setYears(data);
      setIsLoadingDB(false);
    }
  };

  const handleYearChange = async (year: number) => {
    setSelectedYear(year);
    setSelectedChapterId('');
    setChapters([]);

    if (selectedMethodId && year) {
        setIsLoadingDB(true);
        const data = await dbService.getChapters(Number(selectedMethodId), year);
        setChapters(data);
        setIsLoadingDB(false);
    }
  }

  const handleChapterChange = async (chapterId: number) => {
    setSelectedChapterId(chapterId);
    if (chapterId) {
      setIsLoadingDB(true);
      const words = await dbService.getWordsByChapter(chapterId);
      setTextInput(words.join('\n'));
      setIsLoadingDB(false);
    }
  };

  const handleStart = () => {
    const words = textInput
      .split(/[\n,]+/)
      .map(w => w.trim())
      .filter(w => w.length > 0);

    if (words.length === 0) {
      alert("Voer ten minste één woord in om te starten.");
      return;
    }

    onStart({
      words,
      displayDuration: displayTime
    });
  };

  const handleGenerate = async () => {
    if (!topicInput.trim()) return;

    setIsGenerating(true);
    try {
      const words = await generateWordList(topicInput, 15);
      setTextInput(words.join('\n'));
      setActiveTab('manual'); // Switch to manual view to let user edit
    } catch (e) {
      alert("Er ging iets mis bij het genereren.");
    } finally {
      setIsGenerating(false);
    }
  };

  const clearWords = () => {
    if(confirm('Weet je zeker dat je de lijst wilt wissen?')) {
        setTextInput('');
        setSelectedMethodId('');
        setSelectedYear('');
        setSelectedChapterId('');
        setYears([]);
        setChapters([]);
    }
  }

  return (
    <div className="max-w-2xl mx-auto p-6">
      <div className="text-center mb-10">
        <h1 className="text-4xl font-display font-bold text-indigo-600 mb-2">FlitsWoord</h1>
        <p className="text-slate-500">Bereid je flitsles voor de klas voor.</p>
      </div>

      <div className="bg-white rounded-2xl shadow-xl overflow-hidden border border-slate-100">
        {/* Tabs */}
        <div className="flex border-b border-slate-100 overflow-x-auto">
          <button
            onClick={() => setActiveTab('manual')}
            className={`flex-1 py-4 px-4 text-sm font-semibold flex items-center justify-center gap-2 transition-colors whitespace-nowrap ${
              activeTab === 'manual' ? 'bg-indigo-50 text-indigo-600 border-b-2 border-indigo-600' : 'text-slate-500 hover:text-slate-700'
            }`}
          >
            <List size={18} />
            Handmatig
          </button>
          <button
            onClick={() => setActiveTab('method')}
            className={`flex-1 py-4 px-4 text-sm font-semibold flex items-center justify-center gap-2 transition-colors whitespace-nowrap ${
              activeTab === 'method' ? 'bg-blue-50 text-blue-600 border-b-2 border-blue-600' : 'text-slate-500 hover:text-slate-700'
            }`}
          >
            <BookOpen size={18} />
            Methodes
          </button>
          <button
            onClick={() => setActiveTab('ai')}
            className={`flex-1 py-4 px-4 text-sm font-semibold flex items-center justify-center gap-2 transition-colors whitespace-nowrap ${
              activeTab === 'ai' ? 'bg-purple-50 text-purple-600 border-b-2 border-purple-600' : 'text-slate-500 hover:text-slate-700'
            }`}
          >
            <Sparkles size={18} />
            AI Generator
          </button>
        </div>

        <div className="p-8">
          {activeTab === 'manual' && (
            <div className="space-y-4">
              <label className="block text-sm font-medium text-slate-700">
                Typ of plak je woordenlijst (één per regel of gescheiden door komma's)
              </label>
              <div className="relative">
                <textarea
                    value={textInput}
                    onChange={(e) => setTextInput(e.target.value)}
                    placeholder="vis&#10;aap&#10;noot&#10;..."
                    className="w-full h-64 p-4 rounded-xl border border-slate-200 focus:border-indigo-500 focus:ring-2 focus:ring-indigo-200 outline-none resize-none font-display text-lg shadow-inner bg-slate-50 text-slate-900"
                />
                {textInput.length > 0 && (
                     <button 
                        onClick={clearWords}
                        className="absolute top-4 right-4 text-slate-400 hover:text-red-500 transition-colors p-1"
                        title="Lijst wissen"
                     >
                        <Eraser size={20} />
                     </button>
