// databaseService.ts - Dedicated for Staal method
import staal_gr4 from '../data/staal_groep4';
import staal_gr5 from '../data/staal_groep5';

export interface Chapter {
  id: number;
  name: string;
  words: string[];
}

// Types for the nested data structure (Group 5)
interface LessonData {
  les: number;
  words: string[];
}
interface WeekData {
  week: number;
  lessen: LessonData[];
}
interface BlockData {
  blok: number;
  weken?: WeekData[];
  lessen?: LessonData[]; // For blocks without weeks (e.g. 9 & 10)
}

// Registry now holds either the simple format (Gr4) or nested format (Gr5)
const DATA_REGISTRY: Record<number, any> = {
  4: staal_gr4,
  5: staal_gr5
};

export const dbService = {
  getAvailableGroups: (): number[] => {
    return Object.keys(DATA_REGISTRY).map(Number).sort();
  },

  getBlocksForGroup: (group: number): Chapter[] => {
    const rawData = DATA_REGISTRY[group];
    if (!rawData) return [];

    if (group === 5) {
      // Handle nested format
      return (rawData as BlockData[]).map((b) => ({
        id: b.blok,
        name: `Blok ${b.blok}`,
        words: [] // Words are fetched per lesson now
      }));
    } else {
      // Handle simple format (Group 4)
      return (rawData as {name: string, words: string[]}[]).map((b, index) => ({
        id: index + 1, // Use 1-based index for consistency if possible, or just index
        name: b.name,
        words: b.words
      }));
    }
  },

  getWeeks: (group: number, blockId: number): number[] => {
    if (group === 5) {
      const blocks = DATA_REGISTRY[5] as BlockData[];
      const block = blocks.find(b => b.blok === blockId);
      if (block) {
        if (block.weken) {
          return block.weken.map(w => w.week);
        }
        // If block has lessons but no weeks (e.g. Block 9/10), we simulate "Week 1"
        if (block.lessen) {
          return [1];
        }
      }
    }
    // Default fallback
    return [1, 2, 3, 4];
  },

  getLessons: (group: number, blockId: number, week: number): number[] => {
    if (group === 5) {
      const blocks = DATA_REGISTRY[5] as BlockData[];
      const block = blocks.find(b => b.blok === blockId);

      if (block) {
        // Case 1: Standard structure with Weeks
        if (block.weken) {
          const weekData = block.weken.find(w => w.week === week);
          if (weekData) {
            let lessons = weekData.lessen.map(l => l.les);
            // Filter out 3.4 test lesson rule
            if (week === 3) {
                lessons = lessons.filter(l => l !== 4);
            }
            return lessons;
          }
        }
        // Case 2: Direct lessons (Block 9/10)
        // We treat them as being in "Week 1"
        if (block.lessen && week === 1) {
             return block.lessen.map(l => l.les);
        }
      }
      return [];
    }

    // Default fallback for simple structure
    const lessons = [1, 2, 3, 4, 5];
    if (week === 3) {
        return lessons.filter(l => l !== 4);
    }
    return lessons;
  },

  getWordsForLesson: (group: number, blockId: number, week: number, lesson: number): string[] => {
    if (group === 5) {
      const blocks = DATA_REGISTRY[5] as BlockData[];
      const block = blocks.find(b => b.blok === blockId);
      if (block) {
        // Case 1: Standard
        if (block.weken) {
          const weekData = block.weken.find(w => w.week === week);
          const lessonData = weekData?.lessen.find(l => l.les === lesson);
          return lessonData ? lessonData.words : [];
        }
        // Case 2: Direct lessons (Block 9/10)
        if (block.lessen) {
           const lessonData = block.lessen.find(l => l.les === lesson);
           return lessonData ? lessonData.words : [];
        }
      }
      return [];
    }

    // Fallback for Group 4 (Simulated, as we don't have granular data)
    // We just return the whole block's words if we can find it
    const rawData = DATA_REGISTRY[group];
    // Note: getBlocksForGroup returned ID as index+1 for Gr4
    const blockIndex = blockId - 1; 
    if (rawData && rawData[blockIndex]) {
        return rawData[blockIndex].words;
    }

    return [];
  }
};

import React, { useState, useEffect } from 'react';
import { WordConfig } from '../types';
import { dbService, Chapter } from '../services/databaseService';
import { Play, Settings2, BookOpen, GraduationCap, ClipboardList, CalendarDays, BookOpenCheck } from 'lucide-react';

interface SetupScreenProps {
  onStart: (config: WordConfig) => void;
}

const SetupScreen: React.FC<SetupScreenProps> = ({ onStart }) => {
  const [textInput, setTextInput] = useState('');
  const [displayTime, setDisplayTime] = useState(3);

  // Selection State
  const [availableGroups, setAvailableGroups] = useState<number[]>([]);
  const [selectedGroup, setSelectedGroup] = useState<number | ''>('');

  const [availableBlocks, setAvailableBlocks] = useState<Chapter[]>([]);
  const [selectedBlockId, setSelectedBlockId] = useState<number | ''>('');

  const [selectedWeek, setSelectedWeek] = useState<number | ''>('');
  const [availableWeeks, setAvailableWeeks] = useState<number[]>([]);

  const [selectedLesson, setSelectedLesson] = useState<number | ''>('');
  const [availableLessons, setAvailableLessons] = useState<number[]>([]);

  useEffect(() => {
    setAvailableGroups(dbService.getAvailableGroups());
  }, []);

  // Handlers
  const handleGroupChange = (group: number) => {
    setSelectedGroup(group);
    // Reset downstream
    setSelectedBlockId('');
    setSelectedWeek('');
    setSelectedLesson('');
    setTextInput('');
    setAvailableWeeks([]);
    setAvailableLessons([]);

    if (group) {
      setAvailableBlocks(dbService.getBlocksForGroup(group));
    } else {
      setAvailableBlocks([]);
    }
  };

  const handleBlockChange = (blockId: number) => {
    setSelectedBlockId(blockId);
    // Reset downstream
    setSelectedWeek('');
    setSelectedLesson('');
    setTextInput('');
    setAvailableLessons([]);

    if (selectedGroup && blockId) {
        const weeks = dbService.getWeeks(selectedGroup, blockId);
        setAvailableWeeks(weeks);

        // Auto-select week if only 1 is available (e.g. for revision blocks treated as week 1)
        if (weeks.length === 1) {
            handleWeekChange(weeks[0], selectedGroup, blockId);
        }
    } else {
        setAvailableWeeks([]);
    }
  };

  const handleWeekChange = (week: number, groupOverride?: number, blockOverride?: number) => {
    const group = groupOverride || selectedGroup;
    const block = blockOverride || selectedBlockId;

    setSelectedWeek(week);
    setSelectedLesson('');
    setTextInput('');

    if (group && block) {
        // Update available lessons based on week
        const lessons = dbService.getLessons(Number(group), Number(block), week);
        setAvailableLessons(lessons);
    }
  };

  const handleLessonChange = (lesson: number) => {
    setSelectedLesson(lesson);

    if (selectedGroup && selectedBlockId && selectedWeek) {
        const words = dbService.getWordsForLesson(
            Number(selectedGroup), 
            Number(selectedBlockId), 
            Number(selectedWeek), 
            lesson
        );
        setTextInput(words.join('\n'));
    }
  };

  const handleStart = () => {
    const words = textInput
      .split(/[\n,]+/)
      .map(w => w.trim())
      .filter(w => w.length > 0);

    if (words.length === 0) {
      alert("Geen woorden gevonden. Vul de woordenlijst in.");
      return;
    }

    onStart({
      words,
      displayDuration: displayTime
    });
  };

  // derived state for checks
  const isReadyToFlash = textInput.trim().length > 0;

  return (
    <div className="max-w-2xl mx-auto p-6 pt-12">
      <div className="text-center mb-10">
        <div className="inline-flex items-center justify-center w-16 h-16 bg-indigo-100 text-indigo-600 rounded-2xl mb-4">
            <BookOpen size={32} />
        </div>
        <h1 className="text-4xl font-display font-bold text-slate-800 mb-2">Staal Flitshulp</h1>
        <p className="text-slate-500">Oefen de spellingwoorden van Staal met je klas.</p>
      </div>

      <div className="bg-white rounded-3xl shadow-2xl border border-slate-100 p-8 space-y-8">

        {/* Selection Grid */}
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">

          {/* 1. Groep */}
          <div className="space-y-2">
            <label className="text-sm font-bold text-slate-600 flex items-center gap-2">
                <GraduationCap size={16} className="text-indigo-500" />
                Groep
            </label>
            <select 
                value={selectedGroup}
                onChange={(e) => handleGroupChange(Number(e.target.value))}
                className="w-full p-3 rounded-xl border-2 border-slate-100 bg-slate-50 text-slate-800 font-semibold focus:border-indigo-500 focus:bg-white outline-none transition-all cursor-pointer"
            >
                <option value="">Kies groep...</option>
                {availableGroups.map(g => (
                    <option key={g} value={g}>Groep {g}</option>
                ))}
            </select>
          </div>

          {/* 2. Blok */}
          <div className="space-y-2">
            <label className="text-sm font-bold text-slate-600 flex items-center gap-2">
                <ClipboardList size={16} className="text-indigo-500" />
                Blok
            </label>
            <select 
                value={selectedBlockId}
                onChange={(e) => handleBlockChange(Number(e.target.value))}
                disabled={!selectedGroup}
                className="w-full p-3 rounded-xl border-2 border-slate-100 bg-slate-50 text-slate-800 font-semibold focus:border-indigo-500 focus:bg-white outline-none transition-all cursor-pointer disabled:opacity-50"
            >
                <option value="">Kies blok...</option>
                {availableBlocks.map(b => (
                    <option key={b.id} value={b.id}>{b.name}</option>
                ))}
            </select>
          </div>

          {/* 3. Week */}
          <div className="space-y-2">
            <label className="text-sm font-bold text-slate-600 flex items-center gap-2">
                <CalendarDays size={16} className="text-indigo-500" />
                Week
            </label>
            <select 
                value={selectedWeek}
                onChange={(e) => handleWeekChange(Number(e.target.value))}
                disabled={selectedBlockId === '' || availableWeeks.length === 0}
                className="w-full p-3 rounded-xl border-2 border-slate-100 bg-slate-50 text-slate-800 font-semibold focus:border-indigo-500 focus:bg-white outline-none transition-all cursor-pointer disabled:opacity-50"
            >
                <option value="">
                    {availableWeeks.length === 0 ? '-' : 'Kies week...'}
                </option>
                {availableWeeks.map(w => (
                    <option key={w} value={w}>Week {w}</option>
                ))}
            </select>
          </div>

          {/* 4. Les */}
          <div className="space-y-2">
            <label className="text-sm font-bold text-slate-600 flex items-center gap-2">
                <BookOpenCheck size={16} className="text-indigo-500" />
                Les
            </label>
            <select 
                value={selectedLesson}
                onChange={(e) => handleLessonChange(Number(e.target.value))}
                disabled={!selectedWeek || availableLessons.length === 0}
                className="w-full p-3 rounded-xl border-2 border-slate-100 bg-slate-50 text-slate-800 font-semibold focus:border-indigo-500 focus:bg-white outline-none transition-all cursor-pointer disabled:opacity-50"
            >
                <option value="">
                    {availableLessons.length === 0 ? '-' : 'Kies les...'}
                </option>
                {availableLessons.map(l => (
                    <option key={l} value={l}>Les {l}</option>
                ))}
            </select>
          </div>
        </div>

        {/* Preview Area */}
        <div className="space-y-2 pt-4 border-t border-slate-100">
          <label className="text-sm font-bold text-slate-600">
            Woordenlijst voor deze les
          </label>
          <textarea
            value={textInput}
            onChange={(e) => setTextInput(e.target.value)}
            disabled={!selectedLesson}
            placeholder={!selectedLesson ? "Selecteer eerst een les..." : "Woorden laden..."}
            className="w-full h-40 p-4 rounded-2xl border-2 border-slate-100 bg-slate-50 text-slate-700 font-display text-lg focus:border-indigo-500 focus:bg-white outline-none transition-all resize-none shadow-inner disabled:bg-slate-100 disabled:text-slate-400"
          />
          <p className="text-xs text-slate-400 text-right">
             Je kunt de woorden hierboven aanpassen voor de specifieke les.
          </p>
        </div>

        {/* Controls */}
        <div className="flex flex-col sm:flex-row items-center gap-4 pt-2">
          <div className="flex-1 flex items-center gap-3 bg-slate-100 px-5 py-3 rounded-2xl w-full">
            <Settings2 size={20} className="text-slate-400" />
            <div className="flex-1 flex items-center justify-between">
                <span className="text-sm font-bold text-slate-600">Snelheid:</span>
                <select 
                    value={displayTime} 
                    onChange={(e) => setDisplayTime(Number(e.target.value))}
                    className="bg-transparent font-bold text-indigo-600 outline-none cursor-pointer"
                >
                    {[1, 1.5, 2, 3, 5, 8].map(t => (
                        <option key={t} value={t}>{t} sec</option>
                    ))}
                </select>
            </div>
          </div>

          <button
            onClick={handleStart}
            disabled={!isReadyToFlash}
            className="w-full sm:w-auto px-10 py-4 bg-indigo-600 text-white text-xl font-bold rounded-2xl shadow-xl shadow-indigo-100 hover:bg-indigo-700 hover:scale-[1.02] active:scale-95 transition-all flex items-center justify-center gap-3 disabled:bg-slate-300 disabled:shadow-none disabled:scale-100 disabled:cursor-not-allowed"
          >
            <Play size={24} fill="currentColor" />
            Flitsen!
          </button>
        </div>
      </div>

      <p className="text-center mt-8 text-slate-400 text-sm">
        Gemaakt voor en door leerkrachten.
      </p>
    </div>
  );
};

